// Handle both Gitea webhook payload and manual trigger
const body = $input.first().json;

let commitSha = '';
let sessionNumber = 0;
let repoUrl = 'https://gitea.research-ready.nl/api/v1/repos/admin/price-of-dawn';

if (body.commits && body.commits.length > 0) {
  // Gitea webhook payload
  commitSha = body.commits[0].id;
  const modifiedFiles = body.commits[0].modified || body.commits[0].added || [];
  // Detect session number from changed files (e.g. session3.md -> 3)
  for (const f of modifiedFiles) {
    const m = f.match(/session(\d+)\.md/);
    if (m) { sessionNumber = parseInt(m[1]); break; }
  }
} else {
  // Manual trigger — use defaults for testing
  commitSha = body.sha || 'HEAD';
  sessionNumber = body.session_number || 3; // Edit this before manual test run
}

return [{
  json: {
    commitSha,
    sessionNumber,
    repoUrl,
    timestamp: new Date().toISOString()
  }
}];

const sessionText = $input.first().json.data;
const sessionNumber = $('Extract Commit Info').first().json.sessionNumber;

// Extract key content sections — look for scene headings and content
// Pull the first 3000 chars as summary context (full file may be long)
const truncated = typeof sessionText === 'string'
  ? sessionText.substring(0, 4000)
  : JSON.stringify(sessionText).substring(0, 4000);

// Extract scene/event summary — look for ## headings as scene markers
const lines = truncated.split('\n');
const eventLines = [];
let inRelevantSection = false;

for (const line of lines) {
  if (line.startsWith('## Scene') || line.startsWith('## Beat') || line.startsWith('## Encounter')) {
    inRelevantSection = true;
    eventLines.push(line.replace(/^#+\s*/, '- '));
  } else if (line.startsWith('## ') && inRelevantSection) {
    inRelevantSection = false;
  } else if (inRelevantSection && line.trim().length > 20) {
    eventLines.push('  ' + line.trim().substring(0, 120));
  }
  if (eventLines.length > 30) break;
}

const sessionEvents = eventLines.length > 0
  ? eventLines.join('\n')
  : `Session ${sessionNumber} notes — full text:\n` + truncated.substring(0, 1500);

return [{
  json: {
    sessionNumber,
    sessionEvents,
    rawLength: truncated.length
  }
}];

