const sessionNumber = $('Extract Session Events').first().json.sessionNumber;
const today = new Date().toISOString().split('T')[0];

// Pull content from each LLM node
const npcReactions = $('LiteLLM — NPC Reactions').first().json.choices[0].message.content.trim();
const factionShifts = $('LiteLLM — Faction Shifts').first().json.choices[0].message.content.trim();
const worldEvents = $('LiteLLM — World Events').first().json.choices[0].message.content.trim();

// Token usage summary
const totalTokens =
  ($('LiteLLM — NPC Reactions').first().json.usage?.total_tokens || 0) +
  ($('LiteLLM — Faction Shifts').first().json.usage?.total_tokens || 0) +
  ($('LiteLLM — World Events').first().json.usage?.total_tokens || 0);

const doc = `# Living World Report — Session ${sessionNumber}

*Generated: ${today} | Tokens used: ${totalTokens}*

> **GM Note:** This is a generated first draft. Review before session ${sessionNumber + 1}. Edit or delete anything that contradicts player choices or campaign direction. NPC knowledge is constrained to what they could realistically have observed.

---

## NPC Reactions

${npcReactions}

---

## Faction Shifts

${factionShifts}

---

## World Events (between sessions)

${worldEvents}

---

*Living World auto-generated for The Price of Dawn. Edit freely.*
`;

const filename = `living-world/session${sessionNumber}-living-world.md`;

return [{
  json: {
    content: doc,
    filename,
    sessionNumber,
    totalTokens
  }
}];

const reportData = $('Assemble Report').first().json;
const fileCheckResponse = $input.first().json;

// Base64 encode the content
const content = Buffer.from(reportData.content).toString('base64');

// If file exists (200), include SHA for update; if not (404), create new
const body = {
  message: `auto: living world report session ${reportData.sessionNumber}`,
  content: content,
  branch: 'master'
};

if (fileCheckResponse.statusCode === 200 && fileCheckResponse.body?.sha) {
  body.sha = fileCheckResponse.body.sha; // required for updates
}

return [{
  json: {
    filename: reportData.filename,
    body,
    method: fileCheckResponse.statusCode === 200 ? 'PUT' : 'POST',
    sessionNumber: reportData.sessionNumber,
    totalTokens: reportData.totalTokens
  }
}];

const commitResult = $input.first().json;
const prepData = $('Prepare Gitea Commit').first().json;

console.log(`Living World Report committed: session ${prepData.sessionNumber}, ${prepData.totalTokens} tokens used`);
console.log(`File: ${prepData.filename}`);
console.log(`Gitea response: ${commitResult.statusCode || 'unknown'}`);

return [{
  json: {
    success: true,
    sessionNumber: prepData.sessionNumber,
    filename: prepData.filename,
    totalTokens: prepData.totalTokens,
    gitea_sha: commitResult.content?.sha || 'unknown',
    timestamp: new Date().toISOString()
  }
}];
